// Helpers for the midcentury house, batch h1 (plan.md VOCABULARY). Each takes its position (and facing) as arguments.
// Every write goes through put(): only into air, so a cell an earlier part filled is skipped and reported, never
// overwritten. Nothing here writes ground, sand or floor under its footprint. Each helper returns
// { placed, skipped: [[x, y, z, block]] }. Coordinates are plan.md's absolute ones.
import { B, DIRS, OPPOSITE } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

const range = (a, b) => {
  const lo = Math.min(a, b);
  return Array.from({ length: Math.abs(b - a) + 1 }, (_, i) => lo + i);
};
const newOut = () => ({ placed: 0, skipped: [] });
const inBox = (x, z, [x0, x1, z0, z1]) => x >= x0 && x <= x1 && z >= z0 && z <= z1;
const dirName = ([dx, , dz]) => Object.keys(DIRS).find((k) => DIRS[k][0] === dx && DIRS[k][2] === dz);

// the one write path: air only
function put(g, o, x, y, z, [block, state, nbt]) {
  if (!g.isAir(x, y, z)) {
    o.skipped.push([x, y, z, block]);
    return;
  }
  g.set(x, y, z, block, state, nbt);
  o.placed++;
}

// Exterior --------------------------------------------------------------------------------------------------------

/** White stucco fill over the box x0..x1, z0..z1, y0..y1 (plan: y=2..4). */
export function stucco_wall(g, x0, z0, x1, z1, y0 = 2, y1 = 4) {
  const o = newOut();
  for (const x of range(x0, x1)) for (const z of range(z0, z1)) for (const y of range(y0, y1)) {
    put(g, o, x, y, z, ["white_concrete", {}]);
  }
  return o;
}

/**
 * A sliding-door opening, width cells along x from x0 at row z: air at y0..y0+1 (never closed), glass_pane at y0+2.
 * Anything standing in the opening is reported as skipped instead of being removed.
 */
export function slider_gap(g, x0, z, y0 = 2, width = 2) {
  const o = newOut();
  for (const x of range(x0, x0 + width - 1)) {
    for (const y of [y0, y0 + 1]) {
      if (!g.isAir(x, y, z)) o.skipped.push([x, y, z, g.blockAt(x, y, z)]);
    }
    put(g, o, x, y0 + 2, z, B.pane());
  }
  return o;
}

// Plan holes in the roof band: the atrium (x 17..21, z 12..17) and the chimney (x 20..21, z 21..22).
const ATRIUM_HOLE = [17, 21, 12, 17];
const CHIMNEY_HOLE = [20, 21, 21, 22];

/** The eave/ridge slab band over x=9..32 at rows zA..zB, half = "bottom" | "top"; skips the atrium and chimney holes. */
export function roof_band(g, zA, zB, y, half) {
---H2
// Vocabulary helpers from plan.md VOCABULARY, part 2: the ten the brief names. Each takes its position as arguments,
// places blocks through the build library (B.* states), and writes only into air, or over the one block an option
// names (`swap` / `over`). It returns { placed, skipped }: skipped lists [x, y, z, block] for each cell it left alone,
// so the caller can report what an earlier part already owns. Nothing here reaches below its own footprint.
import { B } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

const BEAM_X = [10, 13, 16, 19, 22, 25, 28, 31];   // beam lines every 3 cells from x=10 (plan STRUCTURE)
// plan ROOFS: the z-bands of the main roof, with the y and half each band's slab sits at
// Exterior ----------------------------------------------------------------------------------------------------------

/** header_course: dark_oak_planks along a wall at y (default 5), skipping beam-line x so the roof's logs go there. */
export function header_course(g, x0, x1, z0, z1, y = 5) {
  const t = tally();
  for (const x of span(x0, x1)) for (const z of span(z0, z1)) {
    if (BEAM_X.includes(x)) continue;
    put(g, t, x, y, z, B.block("dark_oak_planks"));
  }
  return t;
}

/** clerestory: glass strip at y along z, with dark_oak_log mullions at x0+3 and x0+6 (plan default x0=22, z=8, y=4). */
}

/** terrazzo_floor: smooth_stone over box [x0,y0,z0,x1,y1,z1] (inclusive) with ~12% light_gray and ~6% white flecks. */
export function terrazzo_floor(g, [x0, y0, z0, x1, y1, z1], { seed = 1 } = {}) {
  const t = tally();
  for (const x of span(x0, x1)) for (const y of span(y0, y1)) for (const z of span(z0, z1)) {
    const r = unit(seed, x, y, z);
    const block = r < 0.12 ? "light_gray_concrete" : r < 0.18 ? "white_concrete" : "smooth_stone";
    put(g, t, x, y, z, B.block(block));
  }
  return t;
}

/**
 * sideboard: a run of len cells from (x, z) along axis. Cabinet fronts are closed birch_trapdoors at y; the top is a
 * birch_slab (top half) at y+1; one potted_cactus sits on the middle cell at y+2.
 */
export function sideboard(g, x, z, len = 2, axis = "x", facing = "south", y = 2) {
---H4
// Vocabulary part 4: glazing, the ledgestone wall, the carport, the car, the front and back fittings, and the
// living, dining and bedroom furniture named in plan.md's VOCABULARY. Every helper takes the grid first, then its
// position (and facing where it has one), and returns { placed, skipped }.
// Each helper writes only into air: a cell already holding a block (an earlier part's, or a sentinel) is left alone
// and counted in `skipped`. Ground and floor are never written, except carport's `floor` option.
import { B, DIRS, OPPOSITE } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

// Writes one block into air only, and counts what it placed and what it left alone.
function writer(g) {
  const out = { placed: 0, skipped: 0 };
  const w = (x, y, z, spec) => {
    const [block, state, nbt] = typeof spec === "string" ? [spec] : spec;
    if (!g.isAir(x, y, z)) { out.skipped++; return; }
    g.set(x, y, z, block, state, nbt);
    out.placed++;
  };
  return { w, out };
}

// The beam lines of the structure: x = 10, 13, 16, ..., 31.
const onBeamLine = (x) => ((x - 10) % 3 + 3) % 3 === 0;

// A per-cell pseudo-random number in [0, 1), so the stone pattern does not depend on write order.
const unit = (x, y, z, seed) => {
  let h = Math.imul(x, 374761393) ^ Math.imul(y, 668265263) ^ Math.imul(z, 2246822519) ^ Math.imul(seed, 3266489917);
  h = Math.imul(h ^ (h >>> 15), 0x85ebca6b);
  h = Math.imul(h ^ (h >>> 13), 0xc2b2ae35);
  return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
};

/**
 * Glass pane run in a wall, y0..y1 inclusive. Default: along x, from x=a to x=b at z=fixed.
 * { along: "z" }: along z, from z=a to z=b at x=fixed.
 */
